WITH ranked AS MATERIALIZED (SELECT result.id_user,"user".steam_name, "user".discord_id,result.time,result.rank,result.points,result.id_record FROM public.track_tournament_result result JOIN public."user" ON "user".id=result.id_user WHERE result.id_tournament=$1), page AS (SELECT * FROM ranked ORDER BY rank,time,id_record LIMIT $2 OFFSET $3) SELECT jsonb_build_object( 'totalCount',(SELECT count(*) FROM ranked),'rows',COALESCE(jsonb_agg(jsonb_build_object( 'userId',page.id_user,'steamName',page.steam_name,'discordId',page.discord_id::text, 'time',page.time,'rank',page.rank,'points',page.points) ORDER BY page.rank,page.time,page.id_record), '[]'::jsonb)) AS value FROM page
